import math
def control(obs):
    h = obs['hitch_deg']
    cam = obs.get('views', {}).get('camera', {})
    pts = cam.get('walls', [])
    ys = []
    for b, d in pts:
        x = d * math.cos(math.radians(b + h))
        y = d * math.sin(math.radians(b + h))
        if -8 < x < -2:
            ys.append(y)
    correction = 0.0
    if ys:
        left = [y for y in ys if y > 0]
        right = [y for y in ys if y < 0]
        if left and right:
            correction = max(-8, min(8, -(min(left) + max(right)) * 1.5))
    return (max(-30, min(30, 1.8*h + correction)), -0.7, -41)

